mapper.update:
UPDATE grupo
SET grup_cupo = #{g.cupo}
WHERE pk_grup_id_grupo = #{id}

mapper.select:
select g.pk_grup_id_grupo
from grupo g
         inner join grado grad on grad.pk_grad_id_grado = g.fk_grup_id_grado
         inner join unidad_educativa ue on ue.pk_uned_id_unidad_educativa = grad.fk_grad_id_unidad_educativa
where grad.fk_grad_id_nivel_grado = #{grado}
  and g.grup_letra = upper(#{letra})
  and ue.uned_rbd = #{rbd}
  and g.fk_grup_id_jornada = #{jornada}
